```java
public class PowerCalculator {
    public static void main(String[] args) {
        try {
            System.out.println(power(2, 3)); // Expected output: 8
            System.out.println(power(-2, 3)); // Expected output: -8 (error handling for negative exponent)
            System.out.println(power(0, 3)); // Expected output: 1 (base case for 0 power)
        } catch (Exception e) {
            System.out.println("An error occurred: " + e.getMessage());
        }
