        if (exponent < 0) {
            throw new Exception("Exponent must be non-negative.");
        }

        if (exponent == 0) {
            return 1;
        }

        // Base case: power of 1 is the number itself
        if (exponent == 0) {
            return 1;
        }

        // Recursive case: power of base with exponent decremented by 1
        return base * power(base, exponent - 1);
    }
}
