def is_palindrome(s):
    return s == s[::-1]

def convert_to_base(n, base):
    if base == 2:
        return bin(n)[2:]  # Remove the '0b' prefix
    elif base == 8:
        return oct(n)[2:]  # Remove the '0o' prefix
    elif base == 16:
        return hex(n)[2:]  # Remove the '0x' prefix
    else:
        return str(n)

def check_all_bases(n):
    # Check in base 10
    if not is_palindrome(str(n)):
