Here's a Python program that implements the social network graph simulation with the specified commands:

```python
class Graph:
    def __init__(self):
        self.graph = {}
        self.graph.setdefault = lambda k: {}

    def add_user(self, username):
        if username not in self.graph:
            self.graph[username] = {}

    def add_friendship(self, username1, username2):
        if username1 in self.graph and username2 in self.graph:
            self.graph[username1][username2] = True
            self.graph[username2][username1] = True

    def shortest_path(self, from_username, to_username):
        if from_username not in self.graph or to_username not in self.graph:
            return 'No connection'

        queue = [(from_username, [from_username])]
        visited = set()

        while queue:
            node, path = queue.pop(0)
            if node == to_username:
                return list(path)

            visited.add(node)
            for neighbor in self.graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

        return 'No connection'

def simulate_social_network():
    graph = Graph()

    while True:
        command = input().strip()
        if command == '':

            from_username, to_username = input().split()
            print(graph.shortest_path(from_username, to_username))

        elif command.startswith('ADD_USER'):
            username = command[5:]
            graph.add_user(username)

        elif command.startswith('ADD_FRIENDSHIP'):
            username1 = command[10]
            username2 = command[14]
            graph.add_friendship(username1, username2)

        else:
            print("Unknown command")

# Run the simulation
simulate_social_network()
```

Explanation:
- The `Graph` class represents the social network graph.
- `add_user` method adds a new user to the graph.
- `add_friendship` method adds a bidirectional friendship between two users.
- `shortest_path` method finds the shortest path between two users using a simple breadth-first search (BFS) approach.
- The `simulate_social_network` function reads commands from the user, processes them, and prints the shortest path when requested.

