```javascript
function fibonacciSequence(max) {
  let sequence = [0, 1];
  while (sequence[sequence.length - 1] <= max) {
    sequence.push(sequence[sequence.length - 1] + sequence[sequence.length - 2]);
  }
  return sequence;
}

const fibSequence = fibonacciSequence(1000);
fibSequence.forEach((num) => console.log(num));
```

