```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class AnomalyDetector
{
    // Method to detect an anomaly in a list of integers
    public static Dictionary<string, object> DetectAnomaly(List<int> lst)
    {
        // Create a sorted version of the input list
        List<int> sortedList = new List<int>(lst);
        sortedList.Sort();

        // Initialize variables to track the anomaly and replacement
        int anomalyIndex = -1;
        int replaceWith = -1;
        int totalReplacements = 0;

        // Loop through the list starting from the second element
        for (int idx = 1; idx < lst.Count; idx++)
        {
            // Check if the current element is less than the previous one
            if (lst[idx] < lst[idx - 1])
            {
                // This is an anomaly
                anomalyIndex = idx;

                // Find the first value in the sorted list that is greater than the previous element
                // and less than the current (anomalous) element
                replaceWith = sortedList.FirstOrDefault(val =>
                    val > lst[idx - 1] && val < lst[idx]);

                // If no such value is found, replaceWith remains -1
                totalReplacements++;

                // Replace the anomaly with the found value
                lst[idx] = replaceWith;
            }
        }

        // Return the result as a dictionary
        Dictionary<string, object> result = new Dictionary<string, object>
        {
            { "anomaly_index", anomalyIndex },
            { "replace_with", replaceWith },
            { "total_replacements", totalReplacements }
        };

        return result;
    }

    // Example usage
    public static void Main()
    {
        List<int> inputList = new List<int> { 1, 3, 2, 4, 5 };
        var result = DetectAnomaly(inputList);

        Console.WriteLine("Anomaly Index: " + result["anomaly_index"]);
        Console.WriteLine("Replace With: " + result["replace_with"]);
        Console.WriteLine("Total Replacements: " + result["total_replacements"]);
        Console.WriteLine("Modified List: " + string.Join(", ", inputList));
    }
}
```

