            if (lst[idx] < lst[idx - 1])
            {
                // Find the nearest value in the sorted list that is greater than the current element
                replaceWith = sortedList.IndexOf((val => val > lst[idx - 1] && val < lst[idx]));

                // If such a value is found, replace the current element
                if (replaceWith != -1)
                {
                    lst[idx] = replaceWith;
                    totalReplacements++;
                }
            }
        }

        // Return the results
        return new Dictionary<string, object>
        {
            { "anomaly_index", anomalyIndex },
            { "replace_with", replaceWith },
            { "total_replacements", totalReplacements }
        };
    }
}
```

### Explanation:
- **`sortedList = sorted(lst)`**: The list is sorted to find potential anomalies.
- **`anomaly_index` and `replace_with`**: Track the position of the anomaly and the value to replace it.
- **`total_replacements`**: Counts how many elements were replaced.
- **`idx` loop**: Iterates through the list starting from index 1 to avoid the first element.

