### ✅ Rust Version

```rust
fn match_order_parens(lst: &[&str]) -> &str {
    let mut parentheses_stack: Vec<char> = Vec::new();

    for item in lst {
        if let Some(c) = item.chars().next() {
            match c {
                '(' => parentheses_stack.push(c),
                ')' => {
                    if parentheses_stack.is_empty() {
                        return "No";
                    }
                    parentheses_stack.pop();
                }
                _ => {} // Ignore non-parentheses characters
            }
        }
    }

    if parentheses_stack.is_empty() {
        "Yes"
    } else {
        "No"
    }
}
