```python
import sys
import string
from collections import defaultdict

def clean_key(key):
    """Clean dictionary key to meet PEP 8 guidelines."""
    return ''.join(c if c.isalnum() else '_' for c in key.lower())

def clean_string(s):
    """Remove punctuation and convert to lowercase."""
    return ''.join(c for c in s.lower() if c.isalnum() or c.isspace())

def process_value(value, depth):
    """Process the value based on its type and depth."""
    if isinstance(value, str):
        cleaned = clean_string(value)
        words = cleaned.split()
        return defaultdict(int, {word: words.count(word) for word in set(words)})
    elif isinstance(value, list):
        merged = ' '.join(value)
        cleaned = clean_string(merged)
        words = cleaned.split()
        return defaultdict(int, {word: words.count(word) for word in set(words)})
    elif isinstance(value, dict) and depth < 3:
        return process_dict(value, depth + 1)
    else:
        return value

def process_dict(d, depth=0):
    """Recursively process the dictionary."""
    result = {}
    for key, value in d.items():
        cleaned_key = clean_key(key)
        processed_value = process_value(value, depth)
        result[cleaned_key] = dict(processed_value)
    return result

if __name__ == "__main__":
    input_dict = eval(sys.stdin.read())
    processed = process_dict(input_dict)
    print(processed)
```

