You can format the output for better readability:

```javascript
function formatResult(result) {
    console.log("Total Duplicates:");
    for (let key in result.totalDuplicates) {
        console.log(`  Element ${key} appears ${result.totalDuplicates[key]} times in total (as duplicates).`);
    }

    console.log("\nPer Array Counts:");
    result.perArrayCounts.forEach((counts, index) => {
        console.log(`  Array ${index + 1}:`);
        for (let key in counts) {
            console.log(`    Element ${key} appears ${counts[key]} times.`);
        }
    });
}
```

