Here's a complete Python program that defines the `Car` class and performs the specified operations:

```python
class Car:
    def __init__(self, make, model, model_year, speed):
        self.make = make
        self.model = model
        self.model_year = model_year
        self.speed = speed
        self.engine_started = False
        self.headlights = False

    def start_engine(self):
        if not self.engine_started:
            print("Engine started.")
        else:
            print("Engine is already started.")

    def accelerate(self, increment):
        if self.engine_started:
            self.speed += increment
            print(f"Speed increased to {self.speed} km/h.")
        else:
            print("Engine is not started.")

    def brake(self, decrement):
        if self.engine_started:
            self.speed -= decrement
            print(f"Speed decreased to {self.speed} km/h.")
            if self.speed < 0:
                print("Speed cannot be decreased below zero.")
        else:
            print("Engine is not started.")

    def honk(self):
        if self.engine_started:
            if self.model_year < 2000:
                print("Beep beep!")
            else:
                print("Vroom vroom!")
        else:
            print("Engine is not started.")

    def toggle_headlights(self):
        if self.headlights:
            self.headlights = False
            print("Headlights turned off.")
        else:
            self.headlights = True
            print("Headlights turned on.")

# Create a Car instance
