  transition: all 0.3s ease;
}

/* Background complement effect */
.neon-background {
  background-color: #ff4d4d;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
}

/* Glow effect */
.neon-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  animation: glow 1s infinite;
}

@keyframes glow {
  0% { transform: translate(-50%, -50%); }
  100% { transform: translate(-50%, -50%); }
}
```

---

