    // Get current color of the button
    const color = button.style.color;

    // Apply neon text effect
    button.classList.add('neon-text');
    button.classList.remove('neon-background');

    // Apply background complement
    button.classList.add('neon-background');
    button.classList.remove('neon-text');

    // Apply glow effect with intensity
    button.classList.add('neon-glow');
    button.style.transition = 'all 0.3s ease';

    // Set transition duration
