using namespace std;

// Define a transaction type that can be deposit, withdrawal, or account creation/deletion
enum class TransactionType {
    DEPOSIT,
    WITHDRAWAL,
    CREATE_ACCOUNT,
    DELETE_ACCOUNT,
    INTEREST,
    FEE
};

// A structure to represent a single transaction
struct Transaction {
    int accountId;
    TransactionType type;
    int amount;
};

// A structure to represent a complex operation involving multiple transactions
struct Operation {
    vector<Transaction> transactions;
    atomic<bool> isCompleted = false;
};

// A function to process a single operation and check for negative balances
vector<int> below_zero(vector<Operation> operations) {
    unordered_map<int, int> accountBalances;
    mutex accountMutex;
    vector<int> accountsBelowZero;
    vector<int> deletedAccounts;

    for (Operation& op : operations) {
        // Simulate concurrent processing
        thread([op, &accountBalances, &accountMutex, &accountsBelowZero, &deletedAccounts]() {
            for (const Transaction& t : op.transactions) {
                lock_guard<mutex> lock(accountMutex);

                if (t.type == TransactionType::CREATE_ACCOUNT) {
                    if (accountBalances.find(t.accountId) == accountBalances.end()) {
                        accountBalances[t.accountId] = 0;
                    }
                } else if (t.type == TransactionType::DELETE_ACCOUNT) {
                    deletedAccounts.push_back(t.accountId);
                    accountBalances.erase(t.accountId);
                } else if (t.type == TransactionType::DEPOSIT || t.type == TransactionType::INTEREST) {
                    accountBalances[t.accountId] += t.amount;
                } else if (t.type == TransactionType::WITHDRAWAL || t.type == TransactionType::FEE) {
                    accountBalances[t.accountId] -= t.amount;
                    if (accountBalances[t.accountId] < 0 && 
                        find(accountsBelowZero.begin(), accountsBelowZero.end(), t.accountId) == accountsBelowZero.end()) {
                        accountsBelowZero.push_back(t.accountId);
                    }
                }
            }
            op.isCompleted = true;
        }).detach();
    }

    // Wait for all operations to complete
    while (any_of(operations.begin(), operations.end(), 
                  [](const Operation& op) { return !op.isCompleted.load(); })) {
        this_thread::sleep_for(chrono::milliseconds(10));
    }

    return accountsBelowZero;
}
