using System;
using System.Text;

class Program
{
    static void Main()
    {
        char[] input = { 'a', 'z', 'x', 'x', 'z', 'y' };
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < input.Length; i++)
        {
            if (result.Length > 0 && result[result.Length - 1] == input[i])
            {
                // Remove the last character if it's the same as current
                result.Length--;
