```java
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Scanner;

/**
 * A small simulation that calculates how long it takes for two cars,
 * starting from the same point and driving in opposite directions,
 * to be a specified distance apart.
 *
 * The program can handle an arbitrary number of car pairs.
 */
public class CarSimulation {

    /** Holds the speeds of a pair of cars. */
    private static class CarPair {
        final double speed1;   // km/h
        final double speed2;   // km/h

        CarPair(double speed1, double speed2) {
            this.speed1 = speed1;
            this.speed2 = speed2;
        }
    }

    /**
     * Computes the time (in hours) for the two cars in {@code pair}
     * to be {@code distanceApart} kilometers apart.
     *
     * @param distanceApart the required separation in km
     * @param pair           the pair of cars
     * @return time in hours
     */
    private static double timeApart(double distanceApart, CarPair pair) {
        // Relative speed = sum of the two speeds (they move away from each other)
        double relativeSpeed = pair.speed1 + pair.speed2;
        return distanceApart / relativeSpeed;   // hours
    }

    /**
     * Checks whether either car in the pair exceeds the given average speed
     * and prints a warning if necessary.
     *
     * @param pair          the pair of cars
     * @param averageSpeed  the average speed threshold
     */
    private static void checkSpeed(CarPair pair, double averageSpeed) {
        if (pair.speed1 > averageSpeed || pair.speed2 > averageSpeed) {
            System.out.println("A car is exceeding the average speed.");
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sc.useLocale(Locale.US);   // ensure '.' is used for decimals

        System.out.print("How many pairs of cars? ");
        int nPairs = sc.nextInt();

        List<CarPair> pairs = new ArrayList<>(nPairs);
        for (int i = 0; i < nPairs; i++) {
            System.out.printf("Pair %d – speed of car 1 (km/h): ", i + 1);
            double s1 = sc.nextDouble();
            System.out.printf("Pair %d – speed of car 2 (km/h): ", i + 1);
            double s2 = sc.nextDouble();
            pairs.add(new CarPair(s1, s2));
        }

        System.out.print("Average speed threshold (km/h): ");
        double avgSpeed = sc.nextDouble();

        System.out.println("\nResults:");
        for (int i = 0; i < nPairs; i++) {
            CarPair pair = pairs.get(i);

            System.out.printf("\nPair %d:%n", i + 1);
            System.out.print("  Target distance apart (km): ");
            double distance = sc.nextDouble();

            double hours = timeApart(distance, pair);
            System.out.printf("  Time to reach %.2f km apart: %.2f hours%n", distance, hours);

            checkSpeed(pair, avgSpeed);
        }

        sc.close();
    }
}
```

