---

## 🚀 C++ Version Using SDL2

```cpp
#include <SDL2/SDL.h>
#include <iostream>

const int SCREEN_WIDTH = 900;
const int SCREEN_HEIGHT = 700;
const int GROUND_Y = 600;
const int GROUND_HEIGHT = 50;

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow("Kirby C++", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    SDL_Event event;
    bool running = true;

    // Colors
    SDL_Color kirby_pink = {255, 105, 180, 255};
    SDL_Color ground_color = {0, 255, 0, 255};
    SDL_Color background_color = {100, 100, 255, 255};

    // Circle properties
    int circle_radius = 25;
    int circle_y_offset = 25;
    int circle_x = 425;
    int circle_y = 500;
    int circle_x_speed = 0;
    int circle_y_speed = 0;
    int gravity = 1;
    int jump_height = -15;
    bool is_crouching = false;
    bool in_air = false;
    bool is_moving_left = false;
    bool is_moving_right = false;
    bool is_floating = false;
    float crouch_scale = 0.5f;

    // Clock
    SDL_Rect rect;
    rect.w = 2 * circle_radius;
    rect.h = 2 * circle_radius;

    while (running) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT)
                running = false;

            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_s:
                        if (!is_crouching) is_crouching = true;
                        break;
                    case SDLK_w:
                        if (!in_air) {
                            circle_y_speed = jump_height;
                            in_air = true;
                        }
                        break;
                    case SDLK_e:
                        if (!is_crouching) is_floating = true;
                        break;
                    case SDLK_r:
                        is_floating = false;
                        break;
                    case SDLK_a:
                        is_moving_left = true;
                        break;
                    case SDLK_d:
                        is_moving_right = true;
                        break;
                }
            }

            if (event.type == SDL_KEYUP) {
                switch (event.key.keysym.sym) {
                    case SDLK_s:
                        is_crouching = false;
                        break;
                    case SDLK_a:
                        is_moving_left = false;
                        break;
                    case SDLK_d:
                        is_moving_right = false;
                        break;
                }
            }
        }

        // Floating setup
        if (is_floating) {
            gravity = 0.3f;
            jump_height = -6.5f;
            in_air = false;
            is_crouching = false;
            circle_radius = 35;
            circle_y_offset = 35;
        } else {
            gravity = 1;
            jump_height = -15;
            in_air = true;
            circle_radius = 25;
            circle_y_offset = 25;
        }

        // Apply gravity
        circle_y_speed += gravity;

        // Apply horizontal motion
        if (is_moving_left)
            circle_x_speed = -5;
        else if (is_moving_right)
            circle_x_speed = 5;
        else
            circle_x_speed = 0;

        // Update position
        circle_x += circle_x_speed;
        circle_y += circle_y_speed;

        // Collision with the ground
        if (circle_y + circle_radius >= GROUND_Y - 5) {
            circle_y = GROUND_Y - 5 - circle_radius;
            circle_y_speed = 0;
            gravity = 1;
            jump_height = -15;
            is_floating = false;
            in_air = false;
        }

        // Collision with screen edges
        if (circle_x < 0) circle_x = 0;
        if (circle_x + 2 * circle_radius > SCREEN_WIDTH) circle_x = SCREEN_WIDTH - 2 * circle_radius;

        // Clear screen
        SDL_SetRenderDrawColor(renderer, background_color.r, background_color.g, background_color.b, background_color.a);
        SDL_RenderClear(renderer);

        // Draw ground
        SDL_SetRenderDrawColor(renderer, ground_color.r, ground_color.g, ground_color.b, ground_color.a);
        rect.x = 0;
        rect.y = GROUND_Y;
        rect.w = SCREEN_WIDTH;
        rect.h = GROUND_HEIGHT;
        SDL_RenderFillRect(renderer, &rect);

        // Draw Kirby circle
        if (is_crouching) {
            rect.x = circle_x;
            rect.y = circle_y + circle_radius;
            rect.w = 2 * circle_radius;
            rect.h = static_cast<int>(crouch_scale * 2 * circle_radius);
            SDL_SetRenderDrawColor(renderer, kirby_pink.r, kirby_pink.g, kirby_pink.b, kirby_pink.a);
            SDL_RenderFillRect(renderer, &rect);
        } else {
            rect.x = circle_x;
            rect.y = circle_y;
            rect.w = 2 * circle_radius;
            rect.h = 2 * circle_radius;
            SDL_RenderFillRect(renderer, &rect);
        }

        // Present renderer
        SDL_RenderPresent(renderer);

        // Cap frame rate
        SDL_Delay(16); // ~60 FPS
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

---

## 📝 Notes

- **SDL2** is used to draw rectangles and simulate a circle using a square.
- A **perfect circle** in SDL2 requires using a pixel-level drawing loop or a **circle drawing function** (not included in base SDL2). This version uses a **square approximation**.
- If you want to **draw a perfect circle**, you can use **SDL2_gfx** (extension for SDL2) or implement a circle drawing algorithm.

---

## 🔄 Optional: Perfect Circle with SDL2_gfx

If you want to draw a perfect circle, install **SDL2_gfx** and use:

```cpp
#include <SDL2/SDL2_gfxPrimitives.h>
...
circleRGBA(renderer, circle_x + circle_radius, circle_y + circle_radius, circle_radius, r, g, b, a);
```

